export default async function install(app){const observers=[],styles=[],icons=new Map(),roots=new WeakSet(),styled=new WeakSet();let stopped=false,queued=false;function schedule(){if(stopped||queued)return;queued=true;queueMicrotask(()=>{queued=false;if(!stopped)scan();});}function walk(root){if(!roots.has(root)){roots.add(root);const o=new MutationObserver(records=>{if(records.some(r=>r.type==='attributes'||[...r.addedNodes].some(n=>n.nodeType===1&&n.localName!=='style')))schedule();});o.observe(root,{childList:true,subtree:true,attributes:true,attributeFilter:['scale','icon']});observers.push(o);}for(const el of root.querySelectorAll('*')){if(el.localName==='calcite-action'&&el.icon==='x'&&el.shadowRoot){if(!styled.has(el.shadowRoot)){styled.add(el.shadowRoot);const s=document.createElement('style');s.textContent='calcite-icon{color:#fff!important;--calcite-icon-color:#fff;}';el.shadowRoot.append(s);styles.push(s);}const icon=el.shadowRoot.querySelector('calcite-icon');if(icon){if(!icons.has(icon))icons.set(icon,icon.scale);if(icon.scale!=='m')icon.scale='m';}}if(el.shadowRoot)walk(el.shadowRoot);}}function scan(){for(const popup of app.view.container.querySelectorAll('.esri-popup'))walk(popup);}const outer=new MutationObserver(schedule);outer.observe(app.view.container,{childList:true,subtree:true});observers.push(outer);app.onCleanup(()=>{stopped=true;observers.forEach(o=>o.disconnect());styles.forEach(s=>s.remove());for(const [icon,scale]of icons)icon.scale=scale;});scan();await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));return {closeIcons:[...icons.keys()].map(icon=>{const r=icon.getBoundingClientRect();return {color:getComputedStyle(icon).color,scale:icon.scale,width:r.width,height:r.height};})};}